/**
 * Block hash computation and manifest validation (§7.6).
 *
 * Implements per-block SHA-256 hashing and manifest integrity validation via CRC-32.
 * The manifest roots the cryptographic chain: beacon → manifest → blocks → whole file.
 *
 * **Why the manifest hash is mandatory:**
 * Without it, a single flipped byte in the manifest packet would yield wrong hashes
 * for hundreds of blocks. Those blocks would fail E12 forever (re-collect, fail,
 * re-collect) with no error code and no termination. The manifest hash detects this
 * corruption immediately and forces re-decode of the manifest.
 *
 * Reference: plan.md §7.2, §7.6, §12 (T1)
 */

import {crc32} from '../frame/crc.js';

/**
 * Compute the SHA-256 hash of a block and truncate it.
 *
 * Per plan.md §7.6, block hashes are SHA-256 truncated to blockHashLen bytes
 * (default 4 bytes). This provides a per-block false accept rate of 2^-32 (~5×10^-6),
 * which across 21,845 blocks (4 GB file) yields ~0.01 expected collisions — comfortably
 * below the whole-file hash's job.
 *
 * **Performance note:** This uses crypto.subtle.digest which is async. For a 192 KB
 * block at 768 fragments, this is called once per block on the sender and once per
 * verified block on the receiver.
 *
 * @param block - Block data (K × L bytes, typically 192 KB)
 * @param blockHashLen - Truncation length (from beacon, typically 4 bytes)
 * @returns Promise resolving to truncated hash bytes
 * @throws {Error} If blockHashLen is invalid or Web Crypto API fails
 */
export async function computeBlockHash(block: Uint8Array, blockHashLen: number): Promise<Uint8Array> {
  if (blockHashLen < 1 || blockHashLen > 32) {
    throw new Error(
      `Invalid blockHashLen: ${blockHashLen} (must be 1-32 bytes for SHA-256 truncation)`
    );
  }

  // Compute full SHA-256 hash
  const fullHash = await crypto.subtle.digest('SHA-256', block);

  // Truncate to blockHashLen bytes
  return new Uint8Array(fullHash).slice(0, blockHashLen);
}

/**
 * Compute the manifest hash (CRC-32) for beacon transmission.
 *
 * The manifest is `blockCount × blockHashLen` bytes containing all block hashes
 * in block order. This function computes its CRC-32 for the beacon's manifestHash
 * field (§7.2), enabling receivers to validate manifest integrity.
 *
 * **Critical:** This CRC-32 is the ONLY integrity check for the manifest data.
 * A corrupted manifest would cause hundreds of blocks to fail verification
 * forever (infinite E12 retry loop). The manifest hash prevents this livelock.
 *
 * @param manifest - Block hash manifest data (blockCount × blockHashLen bytes)
 * @returns CRC-32 checksum (4 bytes as big-endian number)
 */
export function computeManifestHash(manifest: Uint8Array): number {
  return crc32(manifest);
}

/**
 * Validate a decoded manifest against the beacon's hash.
 *
 * After fountain-decoding the manifest (§7.6), the receiver MUST compute its CRC-32
 * and compare against the beacon's manifestHash field. A mismatch indicates manifest
 * corruption and MUST cause the manifest to be discarded and re-decoded.
 *
 * This prevents the infinite E12 failure loop: without validation, a corrupted
 * manifest would cause blocks to fail hash verification forever with no error code
 * or termination.
 *
 * @param manifest - Decoded manifest data (blockCount × blockHashLen bytes)
 * @param beaconManifestHash - 4-byte manifest hash from beacon (§7.2)
 * @returns true if valid, false if corrupted
 * @throws {Error} If inputs are malformed
 */
export function validateManifestHash(
  manifest: Uint8Array,
  beaconManifestHash: Uint8Array
): boolean {
  if (beaconManifestHash.length !== 4) {
    throw new Error(
      `Beacon manifestHash must be 4 bytes, got ${beaconManifestHash.length}`
    );
  }

  if (manifest.length === 0) {
    throw new Error('Manifest data cannot be empty');
  }

  // Compute CRC-32 of decoded manifest
  const computedHash = computeManifestHash(manifest);

  // Convert beacon's 4-byte hash to number (big-endian)
  const beaconHash = (
    (beaconManifestHash[0]! << 24) |
    (beaconManifestHash[1]! << 16) |
    (beaconManifestHash[2]! << 8) |
    beaconManifestHash[3]!
  ) >>> 0; // Force unsigned

  return computedHash === beaconHash;
}

/**
 * Extract a block's hash from the manifest.
 *
 * The manifest stores block hashes sequentially in block order. This helper
 * extracts the hash for a specific block.
 *
 * @param manifest - Block hash manifest (blockCount × blockHashLen bytes)
 * @param blockIndex - Which block's hash to extract
 * @param blockHashLen - Hash length (from beacon)
 * @returns Hash bytes for the requested block
 * @throws {Error} If blockIndex is out of range
 */
export function extractBlockHash(
  manifest: Uint8Array,
  blockIndex: number,
  blockHashLen: number
): Uint8Array {
  const offset = blockIndex * blockHashLen;
  const end = offset + blockHashLen;

  if (end > manifest.length) {
    throw new Error(
      `Block ${blockIndex} hash extends beyond manifest (offset=${offset}, ` +
      `manifestLen=${manifest.length}, blockHashLen=${blockHashLen})`
    );
  }

  return manifest.slice(offset, end);
}

/**
 * Verify a decoded block against its manifest hash.
 *
 * Called after a block reaches rank K and is recovered. If the block's hash
 * doesn't match the manifest, the block is corrupted (E12) and must be re-collected.
 *
 * **Security:** This is the ONLY application-layer check on payload bytes. The
 * per-packet fcrc (CRC-8) is a routing guard, not integrity. QR's Reed-Solomon
 * makes undetected corruption rare but not impossible. This check catches it.
 *
 * @param block - Decoded block data
 * @param blockIndex - Block index (for manifest lookup)
 * @param manifest - Block hash manifest
 * @param blockHashLen - Hash truncation length
 * @returns Promise resolving to true if hash matches, false otherwise
 * @throws {Error} If parameters are invalid
 */
export async function verifyBlockHash(
  block: Uint8Array,
  blockIndex: number,
  manifest: Uint8Array,
  blockHashLen: number
): Promise<boolean> {
  // Extract expected hash from manifest
  const expectedHash = extractBlockHash(manifest, blockIndex, blockHashLen);

  // Compute actual hash of decoded block
  const actualHash = await computeBlockHash(block, blockHashLen);

  // Compare
  if (actualHash.length !== expectedHash.length) {
    throw new Error(
      `Hash length mismatch: computed ${actualHash.length}, expected ${expectedHash.length}`
    );
  }

  // Constant-time compare to avoid timing attacks (though not critical here)
  let match = true;
  for (let i = 0; i < actualHash.length; i++) {
    if (actualHash[i]! !== expectedHash[i]!) {
      match = false;
      // Continue loop for constant-time
    }
  }

  return match;
}

/**
 * Tests for block hash computation and manifest validation (plan.md §7.6).
 *
 * Verifies:
 * - Block hash computation (SHA-256 truncated to blockHashLen)
 * - Manifest hash computation (CRC-32)
 * - Manifest validation against beacon hash
 * - Block hash verification against manifest
 */

import {describe, it, expect} from 'vitest';
import {
  computeBlockHash,
  computeManifestHash,
  validateManifestHash,
  extractBlockHash,
  verifyBlockHash,
} from '../src/core/hash/block-hash.js';

describe('block-hash', () => {
  describe('computeBlockHash', () => {
    it('should compute SHA-256 hash truncated to blockHashLen', async () => {
      const block = new Uint8Array([1, 2, 3, 4, 5]);
      const hash = await computeBlockHash(block, 4);

      // SHA-256 of [1,2,3,4,5] is: 5994471abb01112afcc18159f6cc74b4f21111ac2a1d...
      // Truncated to 4 bytes: 0x59, 0x94, 0x47, 0x1a
      expect(hash).toEqual(new Uint8Array([0x59, 0x94, 0x47, 0x1a]));
    });

    it('should throw for invalid blockHashLen (< 1)', async () => {
      const block = new Uint8Array([1, 2, 3, 4, 5]);
      await expect(computeBlockHash(block, 0)).rejects.toThrow(
        'Invalid blockHashLen'
      );
    });

    it('should throw for invalid blockHashLen (> 32)', async () => {
      const block = new Uint8Array([1, 2, 3, 4, 5]);
      await expect(computeBlockHash(block, 33)).rejects.toThrow(
        'Invalid blockHashLen'
      );
    });

    it('should return different hashes for different blocks', async () => {
      const block1 = new Uint8Array([1, 2, 3, 4, 5]);
      const block2 = new Uint8Array([1, 2, 3, 4, 6]);

      const hash1 = await computeBlockHash(block1, 4);
      const hash2 = await computeBlockHash(block2, 4);

      expect(hash1).not.toEqual(hash2);
    });

    it('should return same hash for same block', async () => {
      const block = new Uint8Array([1, 2, 3, 4, 5]);

      const hash1 = await computeBlockHash(block, 4);
      const hash2 = await computeBlockHash(block, 4);

      expect(hash1).toEqual(hash2);
    });
  });

  describe('computeManifestHash', () => {
    it('should compute CRC-32 of manifest data', () => {
      // CRC-32 of empty array is 0
      expect(computeManifestHash(new Uint8Array([]))).toBe(0);

      // CRC-32 of [0x00, 0x00, 0x00, 0x00] is 0
      expect(computeManifestHash(new Uint8Array([0, 0, 0, 0]))).toBe(0);

      // CRC-32 of [0x01, 0x02, 0x03, 0x04] is 0x5f0f8f5b
      expect(computeManifestHash(new Uint8Array([1, 2, 3, 4]))).toBe(0x5f0f8f5b);
    });

    it('should compute deterministic hashes', () => {
      const data = new Uint8Array([1, 2, 3, 4, 5]);
      const hash1 = computeManifestHash(data);
      const hash2 = computeManifestHash(data);

      expect(hash1).toBe(hash2);
    });

    it('should detect single-bit changes', () => {
      const data1 = new Uint8Array([1, 2, 3, 4]);
      const data2 = new Uint8Array([1, 2, 3, 5]); // Last byte differs by 1 bit

      expect(computeManifestHash(data1)).not.toBe(computeManifestHash(data2));
    });
  });

  describe('validateManifestHash', () => {
    it('should validate correct manifest hash', () => {
      const manifest = new Uint8Array([1, 2, 3, 4]);
      const beaconHash = new Uint8Array([
        (0x5f0f8f5b >>> 24) & 0xff,
        (0x5f0f8f5b >>> 16) & 0xff,
        (0x5f0f8f5b >>> 8) & 0xff,
        0x5f0f8f5b & 0xff,
      ]);

      expect(validateManifestHash(manifest, beaconHash)).toBe(true);
    });

    it('should reject corrupted manifest hash', () => {
      const manifest = new Uint8Array([1, 2, 3, 4]);
      const wrongHash = new Uint8Array([0, 0, 0, 0]);

      expect(validateManifestHash(manifest, wrongHash)).toBe(false);
    });

    it('should throw for malformed beacon hash (wrong length)', () => {
      const manifest = new Uint8Array([1, 2, 3, 4]);
      const shortHash = new Uint8Array([1, 2, 3]);

      expect(() => validateManifestHash(manifest, shortHash)).toThrow(
        'Beacon manifestHash must be 4 bytes'
      );
    });

    it('should throw for empty manifest', () => {
      const emptyManifest = new Uint8Array([]);
      const beaconHash = new Uint8Array([0, 0, 0, 0]);

      expect(() => validateManifestHash(emptyManifest, beaconHash)).toThrow(
        'Manifest data cannot be empty'
      );
    });

    it('should detect single-bit corruption in manifest', () => {
      const originalManifest = new Uint8Array([1, 2, 3, 4]);
      const corruptedManifest = new Uint8Array([1, 2, 3, 5]); // One bit flipped
      const beaconHash = new Uint8Array([
        (0x5f0f8f5b >>> 24) & 0xff,
        (0x5f0f8f5b >>> 16) & 0xff,
        (0x5f0f8f5b >>> 8) & 0xff,
        0x5f0f8f5b & 0xff,
      ]);

      expect(validateManifestHash(originalManifest, beaconHash)).toBe(true);
      expect(validateManifestHash(corruptedManifest, beaconHash)).toBe(false);
    });
  });

  describe('extractBlockHash', () => {
    const manifest = new Uint8Array([
      // Block 0 hash (4 bytes)
      0x01, 0x02, 0x03, 0x04,
      // Block 1 hash (4 bytes)
      0x05, 0x06, 0x07, 0x08,
      // Block 2 hash (4 bytes)
      0x09, 0x0a, 0x0b, 0x0c,
    ]);

    it('should extract block hash at correct offset', () => {
      const hash0 = extractBlockHash(manifest, 0, 4);
      expect(hash0).toEqual(new Uint8Array([0x01, 0x02, 0x03, 0x04]));

      const hash1 = extractBlockHash(manifest, 1, 4);
      expect(hash1).toEqual(new Uint8Array([0x05, 0x06, 0x07, 0x08]));

      const hash2 = extractBlockHash(manifest, 2, 4);
      expect(hash2).toEqual(new Uint8Array([0x09, 0x0a, 0x0b, 0x0c]));
    });

    it('should throw for out-of-range block index', () => {
      expect(() => extractBlockHash(manifest, 3, 4)).toThrow(
        'Block 3 hash extends beyond manifest'
      );
    });

    it('should work with different blockHashLen', () => {
      const shortManifest = new Uint8Array([0x01, 0x02, 0x03, 0x04, 0x05, 0x06]);
      const hash = extractBlockHash(shortManifest, 1, 3);
      expect(hash).toEqual(new Uint8Array([0x04, 0x05, 0x06]));
    });
  });

  describe('verifyBlockHash', () => {
    it('should verify block against matching manifest hash', async () => {
      const block = new Uint8Array([1, 2, 3, 4, 5]);
      const blockHash = await computeBlockHash(block, 4);

      // Create manifest with this hash
      const manifest = new Uint8Array([
        ...blockHash,
        0xff, 0xff, 0xff, 0xff, // Different block
      ]);

      const isValid = await verifyBlockHash(block, 0, manifest, 4);
      expect(isValid).toBe(true);
    });

    it('should reject block with non-matching manifest hash', async () => {
      const block = new Uint8Array([1, 2, 3, 4, 5]);
      const manifest = new Uint8Array([
        0xff, 0xff, 0xff, 0xff, // Wrong hash
        0xff, 0xff, 0xff, 0xff,
      ]);

      const isValid = await verifyBlockHash(block, 0, manifest, 4);
      expect(isValid).toBe(false);
    });

    it('should verify different blocks in same manifest', async () => {
      const block0 = new Uint8Array([1, 2, 3, 4, 5]);
      const block1 = new Uint8Array([5, 4, 3, 2, 1]);

      const hash0 = await computeBlockHash(block0, 4);
      const hash1 = await computeBlockHash(block1, 4);

      const manifest = new Uint8Array([...hash0, ...hash1]);

      expect(await verifyBlockHash(block0, 0, manifest, 4)).toBe(true);
      expect(await verifyBlockHash(block1, 1, manifest, 4)).toBe(true);
    });

    it('should detect corrupted block data', async () => {
      const originalBlock = new Uint8Array([1, 2, 3, 4, 5]);
      const corruptedBlock = new Uint8Array([1, 2, 3, 4, 6]); // One byte flipped

      const hash = await computeBlockHash(originalBlock, 4);
      const manifest = new Uint8Array([...hash]);

      expect(await verifyBlockHash(originalBlock, 0, manifest, 4)).toBe(true);
      expect(await verifyBlockHash(corruptedBlock, 0, manifest, 4)).toBe(false);
    });

    it('should throw for mismatched hash length', async () => {
      const block = new Uint8Array([1, 2, 3, 4, 5]);
      const manifest = new Uint8Array([1, 2]); // Too short

      await expect(verifyBlockHash(block, 0, manifest, 4)).rejects.toThrow(
        'extends beyond manifest'
      );
    });
  });

  describe('integration scenarios', () => {
    it('should handle multi-block manifest (4 GB file scenario)', async () => {
      // A 4 GB file with 192 KB blocks has ~21,845 blocks
      const blockCount = 21845;
      const blockHashLen = 4;
      const manifest = new Uint8Array(blockCount * blockHashLen);

      // Populate manifest with hashes
      for (let i = 0; i < blockCount; i++) {
        const block = new Uint8Array([i, i, i, i, i]);
        const hash = await computeBlockHash(block, blockHashLen);
        manifest.set(hash, i * blockHashLen);
      }

      // Compute manifest hash for beacon
      const manifestHash = computeManifestHash(manifest);
      const beaconHash = new Uint8Array([
        (manifestHash >>> 24) & 0xff,
        (manifestHash >>> 16) & 0xff,
        (manifestHash >>> 8) & 0xff,
        manifestHash & 0xff,
      ]);

      // Validate
      expect(validateManifestHash(manifest, beaconHash)).toBe(true);

      // Verify random blocks
      for (let i = 0; i < 100; i++) {
        const blockIndex = Math.floor(Math.random() * blockCount);
        const block = new Uint8Array([blockIndex, blockIndex, blockIndex, blockIndex, blockIndex]);
        expect(await verifyBlockHash(block, blockIndex, manifest, blockHashLen)).toBe(true);
      }
    });

    it('should detect corruption in large manifest', async () => {
      const blockCount = 1000;
      const blockHashLen = 4;
      const manifest = new Uint8Array(blockCount * blockHashLen);

      // Populate with hashes
      for (let i = 0; i < blockCount; i++) {
        const block = new Uint8Array([i, i, i, i, i]);
        const hash = await computeBlockHash(block, blockHashLen);
        manifest.set(hash, i * blockHashLen);
      }

      // Compute correct beacon hash
      const manifestHash = computeManifestHash(manifest);
      const beaconHash = new Uint8Array([
        (manifestHash >>> 24) & 0xff,
        (manifestHash >>> 16) & 0xff,
        (manifestHash >>> 8) & 0xff,
        manifestHash & 0xff,
      ]);

      expect(validateManifestHash(manifest, beaconHash)).toBe(true);

      // Corrupt one byte in the middle of the manifest
      manifest[Math.floor(manifest.length / 2)] ^= 0xff;

      expect(validateManifestHash(manifest, beaconHash)).toBe(false);
    });
  });
});

